<?php
declare(strict_types=1);namespace App\Interface\Http\Identity\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\DTO\Request\ReplaceAvatarRequestDto;use App\Application\Identity\Service\{AuthService,ProfileAvatarService};use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\{ResponseInterface,ServerRequestInterface,UploadedFileInterface};
final class ProfileAvatarController {public function __construct(private readonly AuthService $auth,private readonly ProfileAvatarService $avatars,private readonly ApiResponseFactory $responses){}public function metadata(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a):ResponseInterface{if(($id=$this->user($r,$s,$a))===null)return$s;return$this->responses->success($s,$this->avatars->metadata($id),(string)$r->getAttribute('request_id'));}public function get(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a):ResponseInterface{if(($id=$this->user($r,$s,$a))===null)return$s;$avatar=$this->avatars->contents($id);if($avatar===null)return$this->responses->problem($s,'RESOURCE_NOT_FOUND','Foto de perfil não encontrada.',404,(string)$r->getAttribute('request_id'));$s->getBody()->write($avatar['contents']);return$s->withHeader('Content-Type',$avatar['mimeType'])->withHeader('Cache-Control','private, max-age=0')->withStatus(200);}public function replace(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a):ResponseInterface{if(($id=$this->user($r,$s,$a))===null)return$s;$file=$r->getUploadedFiles()['avatar']??null;if(!$file instanceof UploadedFileInterface||$file->getError()!==UPLOAD_ERR_OK)return$this->responses->problem($s,'VALIDATION_FAILED','Envie uma imagem válida.',422,(string)$r->getAttribute('request_id'));try{$result=$this->avatars->replace(new ReplaceAvatarRequestDto($id,(string)$file->getStream()));return$this->responses->success($s,$result,(string)$r->getAttribute('request_id'));}catch(\InvalidArgumentException $e){return$this->responses->problem($s,'VALIDATION_FAILED',$e->getMessage(),422,(string)$r->getAttribute('request_id'));}}private function user(ServerRequestInterface $r,ResponseInterface &$s,AccessTokenRequestDto $a):?string{try{return$this->auth->currentUser($a)->id;}catch(\Throwable){$s=$this->responses->problem($s,'UNAUTHENTICATED','Credenciais inválidas ou expiradas.',401,(string)$r->getAttribute('request_id'));return null;}}}
